solution:
fn clamp_buggy(value: Int, min: Int, max: Int) -> Int
  requires: min <= max;
  ensures: result >= min;
  ensures: result <= max;
{
  if value < min { return max; }  // BUG: should return min
  if value > max { return max; }
  return value;
}

// Z3 would find: min=10, max=20, value=0
// result = 20, but ensures requires result >= min (20 >= 10 ✓)
// Wait, that's not a failing case...
// Let's try: value=5, min=10, max=20 → result=20, OK
// Actually the real issue: result should be min when value < min
// Z3 would find ensures: result <= max is OK, but result == value || result == min || result == max would fail

fn main() -> Int {
  return clamp_buggy(0, 10, 20);
}
